/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { load } from '../../../src';
import { sympyStr } from '../../sympy-str';

describe("doctests of sympy.logic.utilities.dimacs", () => {
  it("load('1')", () => {
    expect(sympyStr(load('1'))).toBe('cnf_1');
  });
  it("load('1 2')", () => {
    expect(sympyStr(load('1 2'))).toBe('cnf_1 | cnf_2');
  });
  it("load('1 \\n 2')", () => {
    expect(sympyStr(load('1 \n 2'))).toBe('cnf_1 & cnf_2');
  });
  it("load('1 2 \\n 3')", () => {
    expect(sympyStr(load('1 2 \n 3'))).toBe('cnf_3 & (cnf_1 | cnf_2)');
  });
});
